// Callsite -> repo path -> context name, joined against context-map.json at
// read time (the map is regenerated by every context scan, so nothing is cached).
//
// Rust records and cargo diagnostics carry paths relative to the cargo
// workspace (`src/engine/x.rs`, `db/src/perf.rs`), which is `src-tauri/`;
// WebView and Vite paths are relative to the repo root or absolute.

import fs from "node:fs";
import path from "node:path";
import { REPO_ROOT, slash } from "./paths.mjs";

const ROOT = slash(REPO_ROOT).replace(/\/$/, "");

/** Repo-relative forward-slash path of a record's callsite, or null. */
export function repoPathOf(rec) {
  if (!rec.file) return null;
  let f = slash(rec.file).replace(/^\/@fs\//, "/").replace(/^\.\//, "");
  if (/^[A-Za-z]:\//.test(f) || f.startsWith("/")) {
    const lower = f.toLowerCase();
    if (lower.startsWith(ROOT.toLowerCase() + "/")) return f.slice(ROOT.length + 1);
    return f;
  }
  const cargoRelative = rec.src === "rust" || (rec.src === "toolchain" && rec.tgt === "cargo");
  if (cargoRelative && !f.startsWith("src-tauri/") && !f.startsWith("../")) f = `src-tauri/${f}`;
  return f;
}

/** `file:line` for display. */
export function callsiteOf(rec) {
  let p = repoPathOf(rec);
  if (!p) return "-";
  // Dependency sources: `<home>/.cargo/registry/src/<index>/crate-1.2.3/...` -> `crates.io/crate-1.2.3/...`
  p = p.replace(/^.*\/\.cargo\/registry\/src\/[^/]+\//, "crates.io/");
  return rec.line ? `${p}:${rec.line}` : p;
}

/**
 * Index of context-map.json: exact file -> context, and directory -> the
 * context owning most files under it. Missing map -> empty index.
 */
export function loadContextIndex(mapPath = path.join(REPO_ROOT, "context-map.json")) {
  const files = new Map();
  const dirVotes = new Map();
  let contexts = [];
  try {
    contexts = JSON.parse(fs.readFileSync(mapPath, "utf8")).contexts ?? [];
  } catch {
    return { files, dirs: new Map(), loaded: false };
  }
  for (const ctx of contexts) {
    const name = ctx.name ?? ctx.id;
    for (const raw of ctx.file_paths ?? []) {
      const p = slash(raw).replace(/^\.\//, "");
      if (!files.has(p)) files.set(p, name);
      const parts = p.split("/");
      for (let i = parts.length - 1; i >= 3; i--) {
        const dir = parts.slice(0, i).join("/");
        let votes = dirVotes.get(dir);
        if (!votes) dirVotes.set(dir, (votes = new Map()));
        votes.set(name, (votes.get(name) ?? 0) + 1);
      }
    }
  }
  const dirs = new Map();
  for (const [dir, votes] of dirVotes) {
    let best = null;
    let bestN = 0;
    for (const [name, n] of votes) if (n > bestN) [best, bestN] = [name, n];
    dirs.set(dir, best);
  }
  return { files, dirs, loaded: true };
}

/** Context name for a repo path: exact file, else the deepest owning dir, else `-`. */
export function contextOf(index, repoPath) {
  if (!repoPath || !index) return "-";
  const hit = index.files.get(repoPath);
  if (hit) return hit;
  const parts = repoPath.split("/");
  for (let i = parts.length - 1; i >= 3; i--) {
    const name = index.dirs.get(parts.slice(0, i).join("/"));
    if (name) return name;
  }
  return "-";
}
